mapper.select:
SELECT * FROM plan_item_details
WHERE proposal_item_id = #{proposalItemId} AND user_id = #{userId}
ORDER BY created_at DESC, detail_id DESC

mapper.update:
UPDATE plan_item_details SET status = 'STALE'
 WHERE proposal_item_id = #{proposalItemId} AND user_id = #{userId}
   AND evidence_version <> #{keepVersion} AND status = 'CURRENT'
